html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: #ffffff;
  font-size: 13px;
}

#calendar {
  height: 100vh;
  padding: 8px;
  box-sizing: border-box;
}

.fc-event {
  cursor: pointer;
  border: none !important;
  border-radius: 4px;
  padding: 2px 4px;
  font-weight: 500;
}

.fc-toolbar-title {
  font-size: 1.15rem !important;
  font-weight: 700;
  color: #1e293b;
}

srcDoc.js:
let calendar = null;
appsmith.onReady(() => {
  const calendarEl = document.getElementById('calendar');
  calendar = new FullCalendar.Calendar(calendarEl, {
    initialView: 'timeGridWeek',
    locale: 'fr',
    firstDay: 1,
    // La semaine démarre le lundi

    // Découpage horaire : de 8h à 20h
    slotMinTime: '08:00:00',
    slotMaxTime: '20:00:00',
    expandRows: true,
    // Étire les cases pour éviter de devoir scroller

    headerToolbar: {
      left: 'prev,next today',
      center: 'title',
      right: 'dayGridMonth,timeGridWeek,listMonth'
    },
    buttonText: {
      today: "Aujourd'hui",
      month: 'Mois',
      week: 'Semaine',
      list: 'Liste'
    },
    events: function (info, successCallback, failureCallback) {
      const evts = appsmith.model && appsmith.model.events ? appsmith.model.events : [];
      successCallback(evts);
    },
    eventClick: function (info) {
      // 1. On envoie l'ID cliqué à Appsmith
      appsmith.updateModel({
        selectedId: info.event.id
      });

      // 2. Déclenchement sécurisé de l'action Appsmith
      setTimeout(function () {
        appsmith.triggerEvent("onEventClick");
      }, 100);
    }
  });
  calendar.render();
});

// Rechargement immédiat au changement de mécano
appsmith.onModelChange(model => {
  if (calendar) {
    calendar.refetchEvents();
  }
});

